        _push(`<!--]--></div></div>`);
      } else {
        _push(`<div class="article-detail" data-v-a2b542a9><button class="back-button" data-v-a2b542a9> ← 記事一覧に戻る </button><div class="article-detail-card" data-v-a2b542a9><div class="article-detail-header" data-v-a2b542a9><div class="article-detail-meta" data-v-a2b542a9><span class="detail-category" data-v-a2b542a9>${_ssrInterpolate(_unref(selectedArticle).category)}</span><span class="detail-info" data-v-a2b542a9>${_ssrInterpolate(_unref(selectedArticle).date)} | ${_ssrInterpolate(_unref(selectedArticle).readTime)}</span></div><h1 class="article-detail-title" data-v-a2b542a9>${_ssrInterpolate(_unref(selectedArticle).title)}</h1></div><div class="article-detail-content" data-v-a2b542a9>${_unref(selectedArticle).content ?? ""}</div><div class="article-tags" data-v-a2b542a9><span class="tags-label" data-v-a2b542a9>タグ:</span><div class="tags-list" data-v-a2b542a9><!--[-->`);
        _ssrRenderList(_unref(selectedArticle).tags, (tag) => {
          _push(`<span class="tag-item" data-v-a2b542a9>${_ssrInterpolate(tag)}</span>`);
        });
        _push(`<!--]--></div></div></div></div>`);
      }
      _push(`</div></section></div>`);
    };
  }
});
